#!/usr/bin/env python3
"""Authoritative text-only editorial source for the private psychology draft.

Run with Python 3: python3 editorial-engine/content/pesan-dua-jam/author.py
The characters, message and alternate ending are fictional examples, not people
or a conversation from the study. Reviewer/audience responses are hypotheses.
No media, credentials or human attestation are included here.
"""
from __future__ import annotations
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent

def L(text, purpose, question, action, evidence, payoff, word):
    return dict(text=text, purpose=purpose, viewerQuestion=question,
                visualAction=action, evidence=evidence, nextOrPayoff=payoff,
                wordChoice=word)

def S(id, beat, framing, connection, objects, *lines):
    return dict(id=id, beat=beat, framing=framing, connection=connection,
                objects=[dict(object=o, action=a) for o,a in objects], lines=lines)

